export default async function fetchJobs({ terms, fetch, log }) {
  const base = '{{portal}}/token/acme';
  const { token } = await (await fetch(base + '/session')).json();
  const out = [];
  for (const q of (terms.length ? terms : [''])) {
    const d = await (await fetch(base + '/jobs?q=' + encodeURIComponent(q), { headers: { 'x-session-token': token } })).json();
    log.info('fetched', { q, n: d.data.items.length });
    for (const it of d.data.items) out.push({ external_id: it.key, title: it.label, url: '{{portal}}' + it.link, location: it.where, posted_at: it.ts, search_term: q || undefined });
  }
  return out;
}
